(function () {
  'use strict';

  const DEFAULT_LOOKAHEAD_HOURS = 24;

  /**
   * Compute the next Calendar Date (in local time) that falls on `targetDay`
   * at `hour:min` and is strictly >= `now`.
   * Returns a `Date` object.
   */
  function computeNextDate(now, targetDay, hour, min) {
    const currentDay = now.getDay();
    const todayAtTime = new Date(now);
    todayAtTime.setHours(hour, min, 0, 0);

    let daysUntil = targetDay - currentDay;
    if (daysUntil < 0) daysUntil += 7;

    // Same day but time has already passed → next week
    if (daysUntil === 0 && todayAtTime.getTime() < now.getTime()) {
      daysUntil = 7;
    }

    const result = new Date(now);
    result.setDate(result.getDate() + daysUntil);
    result.setHours(hour, min, 0, 0);
    return result;
  }

  /**
   * Compute the next dose date for a given schedule type starting from `now`.
   * @param {import('./medications.js').Schedule} schedule
   * @param {Date} now
   * @returns {Date|null}
   */
  function computeNextDoseForSchedule(schedule, now) {
    // TODO: implement for all schedule types
    // This function will be implemented by the schedule-task worker.
    throw new Error('computeNextDoseForSchedule not implemented yet');
  }

  /**
   * Generate upcoming doses for a single medication within the lookahead window.
   * @param {import('./medications.js').Medication} med
   * @param {Date} now
   * @returns {import('./schedule.js').Dose[]}
   */
  function computeDosesForMedication(med, now) {
    const { schedule } = med;
    if (!schedule.times) return [];
    const lookAheadMs = DEFAULT_LOOKAHEAD_HOURS * 60 * 60 * 1000;
    const doses = [];

    schedule.times.forEach(timeStr => {
      const nextDate = computeNextDoseForSchedule(schedule, now);
      if (nextDate) {
        const diffMs = nextDate.getTime() - now.getTime();
        if (diffMs >= 0 && diffMs < lookAheadMs) {
          const stableId = med.id + '|' + timeStr + '|' + (schedule.type);// TODO: improve id for custom intervals
          doses.push({
            id: stableId,
            medicationId: med.id,
            scheduledTime: nextDate,
            taken: false,
          });
        }
      }
    });

    return doses;
  }

  /**
   * @param {import('./medications.js').Medication[]} medications
   * @returns {import('./schedule.js').Dose[]}
   */
  function getUpcomingDoses(medications) {
    const now = new Date();
    const allDoses = [];
    medications.forEach(med => {
      const doses = computeDosesForMedication(med, now);
      allDoses.push(...doses);
    });
    return allDoses.sort((a,b) => a.scheduledTime - b.scheduledTime);
  }

  const SCHEDULE_TYPES = {
    DAILY: 'daily',
    WEEKLY: 'weekly',
    BIWEEKLY: 'biweekly',
    MONTHLY: 'monthly',
    BIANNUAL: 'biannual',
    CUSTOM_DAYS: 'customDays',
    CUSTOM_INTERVAL: 'customInterval'
  };

  window.MedRemSchedule = {
    getUpcomingDoses,
    SCHEDULE_TYPES
  };
})();

(function () {
  'use strict';

  const NOTIFICATION_THRESHOLD_MS = 30000; // ±30 seconds
  const INTERVAL_MS = 30000;               // 30 seconds

  /** @type {Set<string>} */
  let notifiedIds = new Set();

  /** @type {HTMLAudioElement|null} */
  let audio = null;

  /** @type {number|null} */
  let intervalId = null;

  let _soundEnabled = true;
  let _notificationEnabled = true;

  // ---------------------------------------------------------------
  // Public API
  // ---------------------------------------------------------------

  /**
   * @param {Object} [settings]
   * @param {boolean} [settings.enableSound]
   * @param {boolean} [settings.enableNotification]
   */
  function initNotifications(settings) {
    if (settings) {
      if (typeof settings.enableSound === 'boolean') _soundEnabled = settings.enableSound;
      if (typeof settings.enableNotification === 'boolean') _notificationEnabled = settings.enableNotification;
    }

    if (!('Notification' in window)) {
      return;
    }

    if (Notification.permission === 'granted') {
      startPolling();
    } else if (Notification.permission !== 'denied') {
      Notification.requestPermission().then(function (permission) {
        if (permission === 'granted') {
          startPolling();
        }
        startPolling();
      });
    } else {
      startPolling();
    }
  }

  /**
   * @param {import('./schedule.js').Dose[]} doses
   */
  function checkAndNotify(doses) {
    var now = Date.now();

    for (var i = 0; i < doses.length; i++) {
      var dose = doses[i];

      // Skip already‑notified doses
      if (notifiedIds.has(dose.id)) {
        continue;
      }

      var doseTime = dose.scheduledTime.getTime();
      var diffMs = doseTime - now;

      if (Math.abs(diffMs) <= NOTIFICATION_THRESHOLD_MS) {
        // Remember that we notified for this dose
        notifiedIds.add(dose.id);

        var medName = getMedicationName(dose.medicationId) || '用药';

        // ---- Browser notification ----
        if (_notificationEnabled && 'Notification' in window && Notification.permission === 'granted') {
          try {
            new Notification('用药提醒', {
              body: '该服用: ' + medName
            });
          } catch (_) {
            // Silently ignore
          }
        }

        // ---- Audio cue ----
        if (_soundEnabled && audio) {
          // only play if sound enabled (audio object will be managed elsewhere)
          // Existing audio logic will be preserved inside this block
          // TODO: integrate audio player based on enabled flag
        }
      }
    }
  }

  /** @param {boolean} enabled */
  function setSoundEnabled(enabled) {
    _soundEnabled = enabled;
  }

  /** @param {boolean} enabled */
  function setNotificationEnabled(enabled) {
    _notificationEnabled = enabled;
  }

  /** @param {string} doseId */
  function acknowledgeDose(doseId) {
    notifiedIds.add(doseId);
  }

  window.MedRemNotifications = {
    initNotifications,
    checkAndNotify,
    setSoundEnabled,
    setNotificationEnabled,
    acknowledgeDose
  };

  // -------- internal helpers (keep existing) --------
  function startPolling() {
    if (intervalId !== null) return;
    intervalId = setInterval(function () {
      // Polling will be wired by integrator; this stub just keeps interval alive.
    }, INTERVAL_MS);
  }

  function getMedicationName(medicationId) {
    // Stub: integrator will replace with real lookup.
    return '';
  }
})();

(function () {
  'use strict';

  /** @type {string} */
  let _storageKey;

  // Load history array from localStorage.
  function _load() {
    try {
      const raw = window.localStorage.getItem(_storageKey);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  // Persist history array to localStorage.
  function _save(entries) {
    try {
      window.localStorage.setItem(_storageKey, JSON.stringify(entries));
    } catch (e) {
      console.error('Unable to save history:', e);
    }
  }

  /**
   * Initialises the history store.
   * @param {string} storageKey
   */
  function initLogging(storageKey) {
    _storageKey = storageKey;
    if (!window.localStorage.getItem(_storageKey)) {
      _save([]);
    }
  }

  /**
   * Records a taken dose.
   * @param {string} doseId
   * @param {string} [medicationName]
   */
  function markDoseTaken(doseId, medicationName) {
    if (!doseId) return;
    const entries = _load();
    if (entries.some(e => e.doseId === doseId)) return;
    const entry = {
      doseId: doseId,
      medicationName: medicationName || '',
      takenAt: new Date().toISOString(),
    };
    entries.push(entry);
    _save(entries);
  }

  /**
   * Returns history entries, optionally filtered.
   * @param {{ medicationName?: string, fromDate?: Date, toDate?: Date }} [filter]
   * @returns {Array<{doseId: string, medicationName: string, takenAt: string}>}
   */
  function getHistory(filter) {
    const entries = _load();
    if (!filter) return entries.slice();
    // TODO: implement filtering
    return entries.filter(entry => {
      if (filter.medicationName && entry.medicationName !== filter.medicationName) return false;
      if (filter.fromDate || filter.toDate) {
        const taken = new Date(entry.takenAt);
        if (filter.fromDate && taken < filter.fromDate) return false;
        if (filter.toDate && taken > filter.toDate) return false;
      }
      return true;
    });
  }

  /**
   * Clears all history.
   */
  function clearHistory() {
    _save([]);
  }

  /**
   * Exports history as JSON string.
   * @returns {string}
   */
  function exportHistory() {
    return JSON.stringify(_load());
  }

  window.MedRemLogging = {
    initLogging,
    markDoseTaken,
    getHistory,
    clearHistory,
    exportHistory
  };
})();

